# -*- coding: utf-8 -*-

import heapq
import json


def _to_int(value, default):
    if value is None or value == "":
        return default
    try:
        return int(value)
    except Exception:
        return default


def _to_point(value, default):
    if value is None or value == "":
        return default

    if isinstance(value, (list, tuple)):
        try:
            return [int(value[0]), int(value[1])]
        except Exception:
            return None

    if isinstance(value, str):
        try:
            parsed = json.loads(value)
            return [int(parsed[0]), int(parsed[1])]
        except Exception:
            return None

    return None


def _to_obstacles(value):
    if value is None or value == "":
        return []
    if isinstance(value, str):
        try:
            value = json.loads(value)
        except Exception:
            try:
                import ast
                value = ast.literal_eval(value)
            except Exception:
                return []
    if not isinstance(value, (list, tuple)):
        return []
    result = []
    for ob in value:
        try:
            if isinstance(ob, str):
                parts = ob.replace("[", "").replace("]", "").split(",")
                result.append([int(parts[0]), int(parts[1])])
            elif isinstance(ob, (list, tuple)):
                if len(ob) >= 2:
                    result.append([int(ob[0]), int(ob[1])])
                elif len(ob) == 1:
                    parts = ob[0].replace("[", "").replace("]", "").split(",")
                    result.append([int(parts[0]), int(parts[1])])
            elif isinstance(ob, dict):
                result.append([int(ob.get("x")), int(ob.get("y"))])
        except Exception:
            continue
    return result


def _to_sensor(value):
    if value is None or value == "":
        return "ultrasonic"

    v = str(value).strip().lower()

    mapping = {
        "infrared": "infrared",
        "红外": "infrared",
        "红外传感器": "infrared",

        "ultrasonic": "ultrasonic",
        "超声波": "ultrasonic",
        "超声波传感器": "ultrasonic",

        "lidar": "lidar",
        "激光雷达": "lidar",
        "激光": "lidar",
    }

    return mapping.get(v, "ultrasonic")


SENSOR_CONFIG = {
    "infrared": {
        "name": "红外传感器",
        "probe": 0.5,
        "radius": 0,
        "tip": "红外探测距离仅0.5m，路径会紧贴障碍物，存在碰撞风险"
    },
    "ultrasonic": {
        "name": "超声波传感器",
        "probe": 2.0,
        "radius": 1,
        "tip": "超声波探测距离2m，路径与障碍物保持1格安全距离"
    },
    "lidar": {
        "name": "激光雷达",
        "probe": 3.0,
        "radius": 2,
        "tip": "激光雷达探测距离3m，路径与障碍物保持2格安全距离"
    },
}


def make_fail(message, sensor="ultrasonic", tip=""):
    sensor_cfg = SENSOR_CONFIG.get(sensor, SENSOR_CONFIG["ultrasonic"])

    return {
        "success": False,
        "data": [],
        "summary": "路径规划失败",
        "path": [],
        "cost": 0,
        "expanded": 0,
        "sensor": sensor,
        "probe_range": sensor_cfg["probe"],
        "safety_tips": tip,
        "tip": tip,
        "message": message
    }


def main(params: dict) -> dict:
    start = _to_point(params.get("start"), [0, 0])
    goal = _to_point(params.get("goal"), [9, 9])
    width = _to_int(params.get("width"), 10)
    height = _to_int(params.get("height"), 10)
    obstacles = _to_obstacles(params.get("obstacles"))
    sensor = _to_sensor(params.get("sensor"))
    sensor_cfg = SENSOR_CONFIG[sensor]

    if start is None or goal is None:
        return make_fail("起点或终点格式错误，应为 [x, y]", sensor)

    if not (1 <= width <= 50 and 1 <= height <= 50):
        return make_fail("地图尺寸需在 1 到 50 之间", sensor)

    if not (0 <= start[0] < width and 0 <= start[1] < height):
        return make_fail("起点超出地图范围", sensor)

    if not (0 <= goal[0] < width and 0 <= goal[1] < height):
        return make_fail("终点超出地图范围", sensor)

    grid = [[0] * width for _ in range(height)]

    for x, y in obstacles:
        if 0 <= x < width and 0 <= y < height:
            grid[y][x] = 1

    if grid[start[1]][start[0]] == 1:
        return make_fail("起点位置是障碍物，请换一个起点", sensor)

    if grid[goal[1]][goal[0]] == 1:
        return make_fail("终点位置是障碍物，请换一个终点", sensor)

    danger_grid = [row[:] for row in grid]
    radius = sensor_cfg["radius"]

    if radius > 0:
        for x, y in obstacles:
            for dy in range(-radius, radius + 1):
                for dx in range(-radius, radius + 1):
                    nx = x + dx
                    ny = y + dy

                    if not (0 <= nx < width and 0 <= ny < height):
                        continue

                    if (nx, ny) == (start[0], start[1]):
                        continue

                    if (nx, ny) == (goal[0], goal[1]):
                        continue

                    if grid[ny][nx] != 1:
                        danger_grid[ny][nx] = 1

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def astar(grid_map):
        def heuristic(x, y):
            return abs(x - goal[0]) + abs(y - goal[1])

        open_heap = [(heuristic(start[0], start[1]), 0, start[0], start[1])]
        g_cost = {(start[0], start[1]): 0}
        came_from = {}
        expanded = 0

        while open_heap:
            f, g, x, y = heapq.heappop(open_heap)

            if (x, y) == (goal[0], goal[1]):
                break

            if g_cost.get((x, y), float("inf")) < g:
                continue

            expanded += 1

            for dx, dy in directions:
                nx = x + dx
                ny = y + dy

                if not (0 <= nx < width and 0 <= ny < height):
                    continue

                if grid_map[ny][nx] == 1:
                    continue

                ng = g + 1

                if ng < g_cost.get((nx, ny), float("inf")):
                    g_cost[(nx, ny)] = ng
                    came_from[(nx, ny)] = (x, y)
                    heapq.heappush(
                        open_heap,
                        (ng + heuristic(nx, ny), ng, nx, ny)
                    )

        if (goal[0], goal[1]) != (start[0], start[1]) and (goal[0], goal[1]) not in came_from:
            return None

        path = []
        cur = (goal[0], goal[1])

        while cur is not None:
            path.append(cur)
            cur = came_from.get(cur)

        path.reverse()

        return path, len(path) - 1, expanded

    result = astar(danger_grid)

    if result is None:
        probe = astar(grid)

        if probe is not None:
            if sensor == "lidar":
                tip = "当前激光雷达安全膨胀2格，通道过窄。建议换超声波或红外传感器，或扩大通道、减少障碍物。"
            elif sensor == "ultrasonic":
                tip = "当前超声波传感器安全膨胀1格，通道过窄。建议换红外传感器，或扩大通道、减少障碍物。"
            else:
                tip = "当前安全距离导致通道过不去，建议扩大通道或减少障碍物。"
        else:
            tip = "障碍物布局完全封死了通路。建议移除部分障碍物，或调整起点、终点位置。"

        return make_fail("没有找到可行路径", sensor, tip)

    path, cost, expanded = result

    data = []
    for i, p in enumerate(path):
        data.append({
            "step": i,
            "x": p[0],
            "y": p[1]
        })

    summary = "传感器：{}（探测{}m）｜起点({},{}) → 终点({},{})，共{}步，路径代价{}，扩展节点{}个".format(
        sensor_cfg["name"],
        sensor_cfg["probe"],
        start[0],
        start[1],
        goal[0],
        goal[1],
        len(path),
        cost,
        expanded
    )

    return {
        "success": True,
        "data": data,
        "summary": summary,
        "path": [[p[0], p[1]] for p in path],
        "cost": cost,
        "expanded": expanded,
        "sensor": sensor,
        "probe_range": sensor_cfg["probe"],
        "safety_tips": sensor_cfg["tip"],
        "tip": sensor_cfg["tip"],
        "message": "路径规划完成"
    }

# -*- coding: utf-8 -*-
import json
import ast


def _p(v, default=0):
    try:
        return int(float(v))
    except Exception:
        return default


def _pt(p):
    if isinstance(p, dict):
        return [_p(p.get("x")), _p(p.get("y"))]
    if isinstance(p, str):
        s = p.strip()
        if s.startswith("{") and s.endswith("}"):
            try:
                d = json.loads(s.replace("'", '"'))
                return [_p(d.get("x")), _p(d.get("y"))]
            except Exception:
                return [0, 0]
        parts = s.replace("[", "").replace("]", "").replace("(", "").replace(")", "").split(",")
        if len(parts) >= 2:
            return [_p(parts[0]), _p(parts[1])]
        return [0, 0]
    if isinstance(p, (list, tuple)) and len(p) >= 2:
        return [_p(p[0]), _p(p[1])]
    return [0, 0]


def _list(v):
    if v is None or v == "":
        return []
    if isinstance(v, str):
        try:
            return json.loads(v)
        except Exception:
            try:
                return ast.literal_eval(v)
            except Exception:
                return []
    if isinstance(v, list):
        return v
    return []


def _norm_path(path):
    return [_pt(x) for x in path if _pt(x) is not None]


def _norm_obs(obstacles):
    out = []
    for o in obstacles:
        try:
            if isinstance(o, str):
                parts = o.replace("[", "").replace("]", "").split(",")
                out.append([_p(parts[0]), _p(parts[1])])
            elif isinstance(o, (list, tuple)):
                if len(o) >= 2:
                    out.append([_p(o[0]), _p(o[1])])
                elif len(o) == 1 and isinstance(o[0], str):
                    parts = o[0].replace("[", "").replace("]", "").split(",")
                    out.append([_p(parts[0]), _p(parts[1])])
            elif isinstance(o, dict):
                out.append([_p(o.get("x")), _p(o.get("y"))])
        except Exception:
            continue
    return out


DIR = {"left": (-1, 0), "right": (1, 0), "up": (0, -1), "down": (0, 1)}
DN = {"left": "左", "right": "右", "up": "下", "down": "上"}


def _legend():
    return [
        {"color": "green-500", "label": "起点"},
        {"color": "red-500", "label": "终点"},
        {"color": "gray-800", "label": "障碍物"},
        {"color": "blue-400", "label": "已走路径"},
        {"color": "yellow-400", "label": "小车"},
    ]


def _try_json(s):
    if not s:
        return None
    t = s.strip()
    if not t.startswith("{"):
        return None
    try:
        return json.loads(t)
    except Exception:
        try:
            return ast.literal_eval(t)
        except Exception:
            return None


def main(params):
    # ---- 第一步：优先解析按钮 JSON（确定性，不靠大模型）----
    j = _try_json(params.get("user_query"))
    if j is not None:
        direction = (j.get("direction") or "").strip().lower()
        pos = _pt(j.get("position"))
        path_so_far = _norm_path(_list(j.get("path_so_far")))
        obstacles = _norm_obs(_list(j.get("obstacles")))
        width = _p(j.get("width"), 8)
        height = _p(j.get("height"), 6)
        sensor = j.get("sensor") or "ultrasonic"
        goal = _pt(j.get("goal")) if j.get("goal") else _pt(params.get("goal"))
        start = _pt(params.get("start"))
    else:
        direction = (params.get("direction") or "").strip().lower()
        obstacles = _norm_obs(_list(params.get("obstacles")))
        width = _p(params.get("width"), 8)
        height = _p(params.get("height"), 6)
        sensor = params.get("sensor") or "ultrasonic"
        goal = _pt(params.get("goal"))
        start = _pt(params.get("start"))
        pos = _pt(params.get("position"))
        path_so_far = _norm_path(_list(params.get("path_so_far")))

    if pos == [0, 0] and start != [0, 0]:
        pos = start[:]
    if not path_so_far:
        path_so_far = [pos[:]]
    elif _pt(path_so_far[-1]) != pos:
        path_so_far.append(pos[:])

    start_cell = path_so_far[0] if path_so_far else pos
    new_pos = pos[:]
    msg = "小车出发！请点击方向按钮指挥小车移动。"

    if direction in DIR:
        dx, dy = DIR[direction]
        nx, ny = pos[0] + dx, pos[1] + dy
        blocked = (nx < 0 or nx >= width or ny < 0 or ny >= height or [nx, ny] in obstacles)
        if blocked:
            new_pos = pos[:]
            msg = "前方是障碍物或地图边缘，无法前行。请换个方向。"
        else:
            new_pos = [nx, ny]
            if [nx, ny] in path_so_far and _pt(path_so_far[-1]) != [nx, ny]:
                idx = path_so_far.index([nx, ny])
                path_so_far = path_so_far[: idx + 1]
                msg = "小车回到 ({},{})".format(nx, ny)
            else:
                path_so_far.append(new_pos[:])
                if new_pos == goal:
                    msg = "到达终点 ({},{})！实验完成。".format(nx, ny)
                else:
                    msg = "小车向{}移动至 ({},{})".format(DN[direction], nx, ny)

    walked = path_so_far[1:-1]
    step = max(0, len(path_so_far) - 1)
    total = max(1, len(path_so_far))
    summary = "当前小车位于 ({},{}), 已走 {} 步。".format(new_pos[0], new_pos[1], step)

    def ry(y):
        return height - 1 - y

    grid = [["gray-100"] * width for _ in range(height)]
    for x, y in obstacles:
        if 0 <= x < width and 0 <= y < height:
            grid[ry(y)][x] = "gray-800"
    if 0 <= start_cell[0] < width and 0 <= start_cell[1] < height:
        grid[ry(start_cell[1])][start_cell[0]] = "green-500"
    if 0 <= goal[0] < width and 0 <= goal[1] < height:
        grid[ry(goal[1])][goal[0]] = "red-500"
    for x, y in walked:
        if 0 <= x < width and 0 <= y < height:
            grid[ry(y)][x] = "blue-400"
    if 0 <= new_pos[0] < width and 0 <= new_pos[1] < height:
        grid[ry(new_pos[1])][new_pos[0]] = "yellow-400"

    return {
        "title": "小车避障路径动画",
        "summary": summary,
        "grid": grid,
        "position": {"x": new_pos[0], "y": new_pos[1]},
        "step": float(step),
        "path_total": float(total),
        "path": path_so_far,
        "sensor": "2.0m",
        "width": float(width),
        "height": float(height),
        "obstacles": obstacles,
        "time_used": str(round(step * 0.4, 1)) + "s",
        "legend": _legend(),
        "message": msg,
    }

# -*- coding: utf-8 -*-

import heapq
import json


SENSOR_CONFIG = {
    "infrared": {
        "name": "红外传感器",
        "probe": 0.5,
        "radius": 0,
        "tip": "红外探测距离仅0.5m，路径会紧贴障碍物，存在碰撞风险。"
    },
    "ultrasonic": {
        "name": "超声波传感器",
        "probe": 2.0,
        "radius": 1,
        "tip": "超声波探测距离2m，路径与障碍物保持1格安全距离。"
    },
    "lidar": {
        "name": "激光雷达",
        "probe": 3.0,
        "radius": 2,
        "tip": "激光雷达探测距离3m，路径与障碍物保持2格安全距离。"
    }
}


def _to_int(value, default):
    if value is None or value == "":
        return default
    try:
        return int(float(value))
    except Exception:
        return default


def _to_point(value, default):
    if value is None or value == "":
        return default

    if isinstance(value, str):
        try:
            value = json.loads(value)
        except Exception:
            return None

    if isinstance(value, (list, tuple)) and len(value) >= 2:
        try:
            return [int(value[0]), int(value[1])]
        except Exception:
            return None

    return None


def _to_obstacles(value):
    if value is None or value == "":
        return []

    if isinstance(value, str):
        try:
            value = json.loads(value)
        except Exception:
            return []

    if not isinstance(value, (list, tuple)):
        return []

    result = []
    for item in value:
        try:
            result.append([int(item[0]), int(item[1])])
        except Exception:
            continue

    return result


def _to_sensor(value):
    if value is None or value == "":
        return "ultrasonic"

    text = str(value).strip().lower()

    mapping = {
        "infrared": "infrared",
        "红外": "infrared",
        "红外传感器": "infrared",

        "ultrasonic": "ultrasonic",
        "超声波": "ultrasonic",
        "超声波传感器": "ultrasonic",

        "lidar": "lidar",
        "激光": "lidar",
        "激光雷达": "lidar"
    }

    return mapping.get(text, "ultrasonic")


def fail_result(message, sensor, width, height, start, goal, obstacles, tip):
    sensor_cfg = SENSOR_CONFIG.get(sensor, SENSOR_CONFIG["ultrasonic"])

    return {
        "success": False,
        "summary": "路径规划失败",
        "message": message,
        "tip": tip,
        "safety_tips": tip,
        "data": [],
        "path": [],
        "cost": 0,
        "expanded": 0,
        "sensor": sensor,
        "probe_range": sensor_cfg["probe"],
        "width": width,
        "height": height,
        "start": start,
        "goal": goal,
        "obstacles": obstacles
    }


def main(params: dict) -> dict:
    start = _to_point(params.get("start"), [0, 0])
    goal = _to_point(params.get("goal"), [9, 9])
    width = _to_int(params.get("width"), 10)
    height = _to_int(params.get("height"), 10)
    obstacles = _to_obstacles(params.get("obstacles"))
    sensor = _to_sensor(params.get("sensor"))

    sensor_cfg = SENSOR_CONFIG[sensor]

    default_tip = "请检查起点、终点、地图尺寸、障碍物坐标和传感器类型是否合理。"

    if start is None or goal is None:
        return fail_result(
            "起点或终点格式错误，应为 [x,y]，例如 [0,0]。",
            sensor, width, height, start, goal, obstacles, default_tip
        )

    if not (1 <= width <= 50 and 1 <= height <= 50):
        return fail_result(
            "地图尺寸不合法，宽度和高度需要在 1 到 50 之间。",
            sensor, width, height, start, goal, obstacles,
            "请把 width 和 height 设置为 1 到 50 之间的整数。"
        )

    if not (0 <= start[0] < width and 0 <= start[1] < height):
        return fail_result(
            "起点超出地图范围。",
            sensor, width, height, start, goal, obstacles,
            "请检查 start，确保 x 在地图宽度范围内，y 在地图高度范围内。"
        )

    if not (0 <= goal[0] < width and 0 <= goal[1] < height):
        return fail_result(
            "终点超出地图范围。",
            sensor, width, height, start, goal, obstacles,
            "请检查 goal，确保 x 在地图宽度范围内，y 在地图高度范围内。"
        )

    grid = [[0 for _ in range(width)] for _ in range(height)]

    for x, y in obstacles:
        if 0 <= x < width and 0 <= y < height:
            grid[y][x] = 1

    if grid[start[1]][start[0]] == 1:
        return fail_result(
            "起点位置是障碍物，请换一个起点。",
            sensor, width, height, start, goal, obstacles,
            "起点不能放在障碍物上，请修改 start 或 obstacles。"
        )

    if grid[goal[1]][goal[0]] == 1:
        return fail_result(
            "终点位置是障碍物，请换一个终点。",
            sensor, width, height, start, goal, obstacles,
            "终点不能放在障碍物上，请修改 goal 或 obstacles。"
        )

    danger_grid = [row[:] for row in grid]
    radius = sensor_cfg["radius"]

    if radius > 0:
        for ox, oy in obstacles:
            for dy in range(-radius, radius + 1):
                for dx in range(-radius, radius + 1):
                    nx = ox + dx
                    ny = oy + dy

                    if not (0 <= nx < width and 0 <= ny < height):
                        continue

                    if [nx, ny] == start or [nx, ny] == goal:
                        continue

                    if grid[ny][nx] != 1:
                        danger_grid[ny][nx] = 1

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def astar(grid_map):
        def h(x, y):
            return abs(x - goal[0]) + abs(y - goal[1])

        open_heap = [(h(start[0], start[1]), 0, start[0], start[1])]
        g_cost = {(start[0], start[1]): 0}
        came_from = {}
        expanded = 0

        while open_heap:
            f, g, x, y = heapq.heappop(open_heap)

            if (x, y) == (goal[0], goal[1]):
                path = []
                cur = (x, y)

                while cur is not None:
                    path.append(cur)
                    cur = came_from.get(cur)

                path.reverse()
                return path, len(path) - 1, expanded

            if g > g_cost.get((x, y), float("inf")):
                continue

            expanded += 1

            for dx, dy in directions:
                nx = x + dx
                ny = y + dy

                if not (0 <= nx < width and 0 <= ny < height):
                    continue

                if grid_map[ny][nx] == 1:
                    continue

                ng = g + 1

                if ng < g_cost.get((nx, ny), float("inf")):
                    g_cost[(nx, ny)] = ng
                    came_from[(nx, ny)] = (x, y)
                    heapq.heappush(open_heap, (ng + h(nx, ny), ng, nx, ny))

        return None

    result = astar(danger_grid)

    if result is None:
        original_result = astar(grid)

        if original_result is not None:
            if sensor == "lidar":
                tip = "当前激光雷达安全距离为2格，通道可能过窄。建议改用超声波或红外传感器，或者扩大通道、减少障碍物。"
            elif sensor == "ultrasonic":
                tip = "当前超声波传感器安全距离为1格，通道可能过窄。建议改用红外传感器，或者扩大通道、减少障碍物。"
            else:
                tip = "当前路径因安全距离限制无法通过，建议扩大通道或减少障碍物。"
        else:
            tip = "障碍物已经完全封死通路。。建议移除部分障碍物，或调整起点、终点位置。"

        return fail_result(
            "没有找到可行路径。",
            sensor, width, height, start, goal, obstacles, tip
        )

    path, cost, expanded = result

    data = []
    for i, point in enumerate(path):
        data.append({
            "step": i,
            "x": point[0],
            "y": point[1]
        })

    summary = "A*算法规划成功，{}从 ({},{}) 行驶至 ({},{}), 共 {} 步，路径代价 {}，扩展节点 {} 个。".format(
        sensor_cfg["name"],
        start[0],
        start[1],
        goal[0],
        goal[1],
        len(path) - 1,
        cost,
        expanded
    )

    return {
        "success": True,
        "summary": summary,
        "message": "路径规划完成",
        "tip": sensor_cfg["tip"],
        "safety_tips": sensor_cfg["tip"],
        "data": data,
        "path": [[p[0], p[1]] for p in path],
        "cost": cost,
        "expanded": expanded,
        "sensor": sensor,
        "probe_range": sensor_cfg["probe"],
        "width": width,
        "height": height,
        "start": start,
        "goal": goal,
        "obstacles": obstacles
    }
